#include "editor_implementation.h"
#include "editor.h"
namespace moon::editor {
bool Editor::tabletBusy()const{return document.strokeActive()||selectionDragging_||floatingDragging_||shapeDragging_||gradientDragging_||fillDragging_||moveDragging_||navigation_.zoomDragging_;}
void Editor::saveTabletVisibility(){if(smoke_||!tabletVisibilityReadable_)return;try{const auto text=std::string("tablet-panel-v1 ")+(tabletVisibility_.visible?"1\n":"0\n");writeExportBytesAtomic(palettePreferencePath().parent_path()/"tablet-panel-v1.txt",{text.begin(),text.end()});}catch(const std::exception& e){status_=U"数位板栏目偏好保存失败："+unicodeText(e.what());}}
void Editor::resetTabletInteraction(){if(tabletPanel_)tabletPanel_->releasePresses();tabletAssist_.reset();ui::Message state(ui::kMouseMoveMessage);syncShortcutTools(state);if(refreshCursor_)refreshCursor_();invalidateRect(canvasViewport());}
void Editor::setTabletVisible(bool value){initializeDocking();docking_.custom=true;tabletVisibility_.manual(value);if(value)docking_.select(10);else{resetTabletInteraction();requestFocus();}saveTabletVisibility();refresh();saveWorkspaceSizes();}
void Editor::createTabletPanel(){tabletPanel_=new TabletAssistPanel(font_,skin_,toolIcons_);addChild(tabletPanel_);tabletPanel_->setVisible(false);tabletPanel_->context=[this]{showColumnContextMenu(Column(10));};tabletPanel_->action=[this](const std::string& id){tabletAction(id);};tabletPanel_->modifier=[this](int index,bool value){tabletAssist_.modifier(document.identity(),index,value);syncTabletPanel();invalidateRect(canvasViewport());};tabletPanel_->sampling=[this](bool value){tabletAssist_.sample(document.identity(),value);ui::Message state(ui::kMouseMoveMessage);syncShortcutTools(state);syncTabletPanel();invalidateRect(canvasViewport());};tabletPanel_->brush=[this](int value,bool opacity){if(tabletBusy()||pending_!=Pending::None)return;auto& profile=brushFeedback_.brushProfiles_[eraser_?1:0];if(opacity)profile.opacity=std::clamp(value,0,100);else profile.size=std::clamp(value,1,64);saveBrushPreferences();refresh();};
 if(!smoke_)try{const auto path=palettePreferencePath().parent_path()/"tablet-panel-v1.txt";if(std::filesystem::exists(path)){std::ifstream in(path);std::string version;int visible=-1;if(!(in>>version>>visible)||version!="tablet-panel-v1"||(visible!=0&&visible!=1))throw std::runtime_error("Invalid tablet panel preferences");tabletVisibility_.visible=visible!=0;}}catch(const std::exception& e){tabletVisibilityReadable_=false;status_=U"数位板栏目偏好读取失败："+unicodeText(e.what());}
 tabletVisibility_.preference(runtimePreferences_.index("tablet.assistPanel"));if(tabletVisibility_.visible){initializeDocking();docking_.custom=true;}menuCommands_.bind("panelTabletAssist",{[this]{setTabletVisible(!tabletVisibility_.visible);},[this]{return pending_==Pending::None;},[this]{return tabletVisibility_.visible;}});
}
void Editor::syncTabletPanel(){if(!tabletPanel_)return;const auto identity=documentOpen_?document.identity():0;if(tabletAssist_.owner&&tabletAssist_.owner!=identity)resetTabletInteraction();const auto before=tabletVisibility_.visible;tabletVisibility_.preference(runtimePreferences_.index("tablet.assistPanel"));if(before!=tabletVisibility_.visible){if(tabletVisibility_.visible){initializeDocking();docking_.custom=true;docking_.select(10);}else resetTabletInteraction();}TabletAssistSnapshot v;v.enabled=documentOpen_&&!homeOpen_&&pending_==Pending::None;v.busy=tabletBusy();v.undo=document.canUndo();v.redo=document.canRedo();v.eraser=eraser_;v.selection=bool(document.selection());if(v.selection){v.width=document.selection()->width;v.height=document.selection()->height;}v.zoom=zoom_;v.angle=viewRotation_.degrees;v.size=brushFeedback_.brushProfiles_[eraser_?1:0].size;v.opacity=brushFeedback_.brushProfiles_[eraser_?1:0].opacity;v.selectionMode=selectionMode_;v.box=tabletAssist_.owner==identity&&tabletAssist_.boxMove;v.latch=tabletAssist_.owner==identity&&tabletAssist_.latched;v.sample=tabletAssist_.owner==identity&&tabletAssist_.sampling;for(int i=0;i<3;++i)v.modifiers[i]=tabletAssist_.modifier(identity,i);tabletPanel_->sync(v);}
void Editor::layoutTabletPanel(){if(!tabletPanel_)return;const bool show=columnShown(10)&&documentOpen_&&!homeOpen_;tabletPanel_->setVisible(show);if(!show){tabletPanel_->releasePresses();return;}auto chrome=PanelChromeLayout(columnFrame(10),columnFrameTop(10)==0,0);if(columnFloating(10)){const auto f=columnFrame(10);chrome.content={f.x+UiSpacing::related,FloatingColumnChrome::bodyTop(f),f.w-2*UiSpacing::related,std::max(0,f.y2()-UiSpacing::related-FloatingColumnChrome::bodyTop(f))};}tabletPanel_->setBounds(toDisplay(chrome.content));}
void Editor::observeTabletInput(ui::Message* msg){if(auto focus=dynamic_cast<ui::FocusMessage*>(msg);focus&&msg->type()==ui::kFocusLeaveMessage&&!focus->newFocus())resetTabletInteraction();if(auto mouse=dynamic_cast<ui::MouseMessage*>(msg);mouse&&msg->type()==ui::kMouseDownMessage&&mouse->pointerType()==os::PointerType::Touch&&tabletVisibility_.touch())setTabletVisible(true);}

void Editor::tabletAction(const std::string& id){if(!documentOpen_||homeOpen_||pending_!=Pending::None)return;if(tabletBusy()&&id!="confirm"&&id!="cancel")return;paletteFocused_=false;
 if(id=="undo"||id=="redo"){playing_=false;if(id=="undo"){document.undo();status_=U"已撤销";}else{document.redo();status_=U"已重做";}}
 else if(id=="pencil"||id=="eraser")runShortcutCommand(id=="pencil"?"tool.pencil":"tool.eraser");
 else if(id=="hold"||id=="latch")tabletAssist_.latch(document.identity(),id=="latch");
 else if(id=="replace"||id=="add"||id=="subtract"||id=="intersect")selectionMode_=id=="replace"?0:id=="add"?1:id=="subtract"?2:3;
 else if(id=="boundary"||id=="pixels"){if(id=="boundary")document.commitFloatingPaste();useSelectionTool();selectionMode_=0;tabletAssist_.move(document.identity(),id=="boundary");}
 else if(id=="transform"){tabletAssist_.move(document.identity(),false);startFreeSelectionTransform();}
 else if(id=="left"||id=="up"||id=="down"||id=="right"){const int dx=id=="left"?-1:id=="right"?1:0,dy=id=="up"?-1:id=="down"?1:0;if(document.selection()){if(tabletAssist_.owner==document.identity()&&tabletAssist_.boxMove){document.prepareSelectionBoxMove();auto before=document.selection(),after=before;after->x=std::max(0,std::min(document.width()-after->width,after->x+dx));after->y=std::max(0,std::min(document.height()-after->height,after->y+dy));document.previewSelection(after);document.commitSelectionBox(before);}else document.nudgeSelectionContent(dx,dy,frameSelectionExplicit_);}}
 else if(id=="deselect"){document.commitFloatingPaste();document.commitSelection(document.selection(),{});}
 else if(id=="rotation")setViewRotation(0);
 else if(id=="100"||id=="fit"){const auto area=canvasViewport();zoom_=id=="100"?1:std::max(.01,std::min((double(area.w)/uiScale-40)/document.width(),(double(area.h)/uiScale-40)/document.height()));canvas_={area.x+(area.w-int(std::lround(document.width()*canvasScale())))/2,area.y+(area.h-int(std::lround(document.height()*canvasScale())))/2,int(std::lround(document.width()*canvasScale())),int(std::lround(document.height()*canvasScale()))};layoutCanvasScrollBars();}
 else if(id=="confirm"||id=="cancel"){requestFocus();const auto code=id=="confirm"?ui::kKeyEnter:ui::kKeyEsc;ui::KeyMessage down(ui::kKeyDownMessage,code,ui::kKeyNoneModifier,0,0),up(ui::kKeyUpMessage,code,ui::kKeyNoneModifier,0,0);onProcessMessage(&down);onProcessMessage(&up);}
 refresh();}
}

namespace moon::editor {
void Editor::smokeTabletAssist(){
 auto check=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};smoke_=true;documentOpen_=true;homeOpen_=false;pending_=Pending::None;document=Document(8,8);tabletVisibility_={};resetTabletInteraction();refresh();check(tabletPanel_&&menuCommands_.connected("panelTabletAssist"),"Tablet actual panel/menu binding");
 const auto initial=document.historySize();menuCommands_.invoke("panelTabletAssist");check(tabletVisibility_.visible&&tabletPanel_->isVisible(),"Tablet menu show native panel");check(columnFloating(10),"Tablet legacy default floating dock");check(document.historySize()==initial,"Tablet visibility does not alter document");
 tabletPanel_->action("eraser");check(eraser_,"Tablet actual eraser tool");tabletPanel_->action("pencil");check(!eraser_,"Tablet actual pencil tool");tabletPanel_->brush(17,false);tabletPanel_->brush(37,true);check(brushFeedback_.brushProfiles_[0].size==17&&brushFeedback_.brushProfiles_[0].opacity==37,"Tablet shared brush profile");
 document.beginStroke({0,0},0xff123456);document.commitStroke();const auto committed=document.historyPosition();tabletPanel_->action("undo");check(document.historyPosition()+1==committed,"Tablet actual undo");tabletPanel_->action("redo");check(document.historyPosition()==committed,"Tablet actual redo");document.beginStroke({2,2},0xffabcdef);tabletPanel_->action("undo");check(document.historyPosition()==committed,"Tablet gesture lock blocks undo");document.cancelStroke();
 tabletPanel_->action("latch");tabletPanel_->modifier(0,true);check(tabletAssist_.modifier(document.identity(),0),"Tablet latch constrain");tabletPanel_->action("hold");check(!tabletAssist_.modifier(document.identity(),0),"Tablet mode switch releases latch");moveHeldKeys_.insert("Shift");tabletPanel_->modifier(0,true);tabletPanel_->modifier(0,false);check(moveHeldKeys_.count("Shift"),"Tablet release preserves physical modifier");moveHeldKeys_.clear();
 tabletPanel_->sampling(true);check(eyedropperHeld_,"Tablet momentary sample activates effective tool");tabletPanel_->sampling(false);check(!eyedropperHeld_,"Tablet sample release restores effective tool");
 document.commitSelection({},SelectionMask{1,1,2,2,{}});tabletPanel_->action("boundary");const auto pixels=document.canvasPixels();tabletPanel_->action("right");check(document.selection()->x==2&&document.canvasPixels()==pixels,"Tablet boundary nudge retains pixels");tabletPanel_->action("undo");check(document.selection()->x==1,"Tablet boundary nudge undo");
 auto right=dynamic_cast<TabletPressButton*>(tabletPanel_->control("right"));check(right,"Tablet actual repeat button");const auto at=right->bounds().center();ui::MouseMessage down(ui::kMouseDownMessage,os::PointerType::Touch,ui::kButtonLeft,ui::kKeyNoneModifier,at),up(ui::kMouseUpMessage,os::PointerType::Touch,ui::kButtonLeft,ui::kKeyNoneModifier,at);right->onProcessMessage(&down);right->onProcessMessage(&up);check(document.selection()->x==2,"Tablet pointer down executes once and release does not duplicate");
 tabletPanel_->modifier(2,true);tabletPanel_->sampling(true);ui::FocusMessage blur(ui::kFocusLeaveMessage,this,nullptr);observeTabletInput(&blur);check(!tabletAssist_.owner&&!tabletAssist_.sampling,"Tablet window blur releases interaction");tabletPanel_->modifier(1,true);document=Document(8,8);syncTabletPanel();check(!tabletAssist_.owner,"Tablet document switch clears interaction");
 tabletVisibility_={};setTabletVisible(false);observeTabletInput(&down);check(tabletVisibility_.visible,"Tablet real touch message route first detection");setTabletVisible(false);observeTabletInput(&down);check(!tabletVisibility_.visible,"Tablet manual close remains closed after first touch");tabletVisibility_.preference(2);observeTabletInput(&down);check(!tabletVisibility_.visible,"Tablet off mode ignores touch");setTabletVisible(true);tabletPanel_->action("100");check(zoom_==1,"Tablet native 100 percent action");refresh();writeSmokeFrame(display()->nativeSurface().get(),assets_.parent_path()/"tablet-panel-smoke.bmp");
}
}
